package com.rezoxnemesis.videostudio;
import org.json.*;
import org.junit.*;
import org.junit.runner.RunWith;
import org.robolectric.*;
import org.robolectric.annotation.*;
import static org.junit.Assert.*;

@RunWith(RobolectricTestRunner.class) @Config(sdk=33,manifest=Config.NONE) @GraphicsMode(GraphicsMode.Mode.NATIVE)
public class SketchRigRegionTest {
 static JSONObject region()throws Exception{return new JSONObject().put("fixedJointId","fixed").put("movingJointId","moving").put("start",new JSONArray("[.2,.5]")).put("end",new JSONArray("[.8,.5]")).put("radiusPx",100);}
 static JSONObject line()throws Exception{return SketchEditOps.completeObject(new JSONObject().put("id","authored_ink").put("kind","stroke").put("points",new JSONArray("[[.2,.5,1],[.5,.5,1],[.8,.5,1],[.5,.9,1]]")));}
 @Test public void sourceWorldFormulaEndpointsFalloffAndPositiveInfluences()throws Exception {
  java.util.Set<String> joints=java.util.Set.of("fixed","moving");JSONArray w=SketchRigRegion.weights(line(),region(),"moving",joints,1000,1000);assertEquals(1,w.getJSONObject(0).getDouble("fixed"),0);assertEquals(.5,w.getJSONObject(1).getDouble("moving"),1e-12);assertEquals(1,w.getJSONObject(2).getDouble("moving"),0);assertEquals(1,w.getJSONObject(3).getDouble("fixed"),0);
  for(int i=0;i<w.length();i++){JSONObject entry=w.getJSONObject(i);double sum=0;java.util.Iterator<String> names=entry.keys();while(names.hasNext()){double value=entry.getDouble(names.next());assertTrue(value>0);sum+=value;}assertEquals(1,sum,1e-12);}
  JSONObject moved=line();moved.getJSONObject("transform").put("x",.1);JSONArray shifted=SketchRigRegion.weights(moved,region(),"moving",joints,1000,1000);assertTrue(shifted.getJSONObject(0).getDouble("moving")>0);
  JSONObject same=region().put("end",new JSONArray("[.2,.5]"));assertThrows(IllegalArgumentException.class,()->SketchRigRegion.weights(line(),same,"moving",joints,1000,1000));assertThrows(IllegalArgumentException.class,()->SketchRigRegion.validate(region(),"fixed",joints));assertThrows(IllegalArgumentException.class,()->SketchRigRegion.validate(region().put("radiusPx","100"),"moving",joints));assertThrows(IllegalArgumentException.class,()->SketchRigRegion.weights(line(),region().put("start",new JSONArray("[2,2]")).put("end",new JSONArray("[3,3]")),"moving",joints,1000,1000));
 }
 static JSONObject program()throws Exception {
  JSONObject binding=new JSONObject().put("objectId","ink").put("jointId","moving").put("region",region());JSONArray joints=new JSONArray().put(new JSONObject().put("id","fixed").put("x",.2).put("y",.5)).put(new JSONObject().put("id","moving").put("parent","fixed").put("x",.5).put("y",.5));JSONArray poses=new JSONArray().put(new JSONObject().put("frame",0).put("rotations",new JSONObject().put("moving",0))).put(new JSONObject().put("frame",47).put("rotations",new JSONObject().put("moving",12))).put(new JSONObject().put("frame",95).put("rotations",new JSONObject().put("moving",0)));
  return new JSONObject().put("schema",SketchAnimationCompiler.SCHEMA).put("frameCount",96).put("fps",24).put("rigs",new JSONArray().put(new JSONObject().put("id","actor").put("joints",joints).put("bindings",new JSONArray().put(binding)).put("poses",poses)));
 }
 @Test public void regionalPathBakingRetainsOneEditablePathAndMatchesNativePreview()throws Exception {
  JSONObject d=SketchDocument.create(new JSONObject().put("sketchId","regional_ink").put("width",256).put("height",256).put("frameCount",1).put("background","#00000000"));JSONObject ink=SketchEditOps.completeObject(new JSONObject().put("id","ink").put("kind","path").put("commands",new JSONArray("[['M',.2,.5],['C',.4,.5,.6,.5,.8,.5]]")));d.getJSONArray("layers").getJSONObject(0).getJSONArray("objects").put(ink);JSONObject p=program(),before=SketchDocument.copy(p),compiled=SketchAnimationCompiler.compile(d,p,"regional_baked").getJSONObject("document");assertEquals(SketchDocument.canonical(before),SketchDocument.canonical(p));JSONArray output=compiled.getJSONArray("layers").getJSONObject(0).getJSONArray("objects");assertEquals(1,output.length());assertEquals(96,output.getJSONObject(0).getJSONArray("shapeKeys").length());assertEquals("ink",output.getJSONObject(0).getString("id"));
  SketchAnimationCompiler.Sampler sampler=SketchAnimationCompiler.prepare(d,p);for(int frame:new int[]{0,24,47,72,95}){JSONObject preview=sampler.preview(frame,"regional_preview").getJSONObject("document");JSONArray wanted=preview.getJSONArray("layers").getJSONObject(0).getJSONArray("objects").getJSONObject(0).getJSONArray("commands"),actual=SketchShapeKeys.commandsAt(output.getJSONObject(0),frame);assertEquals(SketchDocument.canonical(new JSONObject().put("commands",wanted)),SketchDocument.canonical(new JSONObject().put("commands",actual)));try(SketchFrameRenderer a=new SketchFrameRenderer(RuntimeEnvironment.getApplication(),preview);SketchFrameRenderer b=new SketchFrameRenderer(RuntimeEnvironment.getApplication(),compiled)){android.graphics.Bitmap pa=a.render(0,false),pb=b.render(frame,false);try{int[] x=new int[256*256],y=new int[x.length];pa.getPixels(x,0,256,0,0,256,256);pb.getPixels(y,0,256,0,0,256,256);assertArrayEquals(x,y);}finally{pa.recycle();pb.recycle();}}}
  JSONObject conflict=SketchDocument.copy(p);conflict.getJSONArray("rigs").getJSONObject(0).getJSONArray("bindings").getJSONObject(0).put("weights",new JSONArray());assertThrows(IllegalArgumentException.class,()->SketchAnimationCompiler.compile(d,conflict,"bad_output"));
 }
 @Test public void onlyNewMeshFieldNumbersNormalizeAcrossNativeWireSerialization()throws Exception {
  JSONObject legacy=new JSONObject().put("number",1.0).put("nested",new JSONObject().put("value",2.0));assertEquals(SketchDocument.canonical(legacy),SketchDocument.canonical(SketchPaintMesh.normalizeFeatureFields(legacy)));
  JSONObject request=SketchDocument.copy(legacy).put("number",1.0);JSONObject mesh=SketchPaintMesh.regular(1,1);mesh.getJSONArray("points").getJSONArray(0).put(0,0.0);request.put("patch",new JSONObject().put("paintMesh",mesh));JSONObject normalized=SketchPaintMesh.normalizeFeatureFields(request);assertEquals("java.lang.Double",normalized.get("number").getClass().getName());assertEquals("java.lang.Integer",normalized.getJSONObject("patch").getJSONObject("paintMesh").getJSONArray("points").getJSONArray(0).get(0).getClass().getName());assertTrue(mesh.getJSONArray("points").getJSONArray(0).get(0) instanceof Double);
 }
 @Test public void nativePaintAndInkBakeTogetherWithoutReplacingTheOwnedTexture()throws Exception {
  java.util.concurrent.ExecutorService worker=java.util.concurrent.Executors.newSingleThreadExecutor();try{worker.submit(()->{try{
   android.content.Context c=RuntimeEnvironment.getApplication();String id="region_paint_"+java.util.UUID.randomUUID();SketchEditOps.execute(c,"sketch_create",new JSONObject().put("sketchId",id).put("operationId","create").put("width",256).put("height",256).put("frameCount",1).put("background","#00000000"));JSONObject ink=SketchEditOps.completeObject(new JSONObject().put("id","ink").put("kind","path").put("commands",new JSONArray("[['M',.2,.5],['C',.4,.5,.6,.5,.8,.5]]")));
   SketchPaintMeshTest.edit(c,id,1,"source",new JSONArray().put(new JSONObject().put("type","add_paint_cel").put("layerId","layer_1").put("objectId","paint")).put(new JSONObject().put("type","add_object").put("layerId","layer_1").put("object",ink)));
   SketchPaintMeshTest.edit(c,id,2,"pigment",new JSONArray().put(new JSONObject().put("type","paint_stroke").put("objectId","paint").put("strokeId","owned_sleeve").put("points",new JSONArray("[[.2,.5,1],[.8,.5,1]]")).put("brush",new JSONObject().put("mode","paint").put("color","#FFD0C6DC").put("sizePx",24))).put(new JSONObject().put("type","update_object").put("objectId","paint").put("patch",new JSONObject().put("paintMesh",SketchPaintMesh.regular(4,4)))));
   JSONObject source=SketchPaintMeshTest.load(c,id),p=program();p.getJSONArray("rigs").getJSONObject(0).getJSONArray("bindings").put(new JSONObject().put("objectId","paint").put("jointId","moving").put("region",region()));JSONObject compiled=SketchAnimationCompiler.compile(source,p,"paint_region_baked").getJSONObject("document"),paint=SketchDocument.object(compiled,"paint");assertEquals(2,compiled.getJSONArray("layers").getJSONObject(0).getJSONArray("objects").length());assertEquals(96,paint.getJSONObject("paintMesh").getJSONArray("keys").length());assertEquals(SketchDocument.canonical(SketchDocument.object(source,"paint").getJSONObject("paint")),SketchDocument.canonical(paint.getJSONObject("paint")));assertEquals(96,SketchDocument.object(compiled,"ink").getJSONArray("shapeKeys").length());
   String animation="paint_region_"+java.util.UUID.randomUUID(),output="paint_baked_"+java.util.UUID.randomUUID();SketchAnimationOps.execute(c,"sketch_animation_save",new JSONObject().put("animationId",animation).put("sketchId",id).put("sourceRevision",source.getLong("revision")).put("expectedRevision",0).put("operationId","save").put("program",p));SketchAnimationOps.execute(c,"sketch_animation_bake",new JSONObject().put("animationId",animation).put("expectedRevision",1).put("operationId","bake").put("outputSketchId",output));compiled=SketchPaintMeshTest.load(c,output);assertEquals(96,SketchDocument.object(compiled,"paint").getJSONObject("paintMesh").getJSONArray("keys").length());assertEquals(SketchDocument.canonical(source),SketchDocument.canonical(SketchPaintMeshTest.load(c,id)));SketchAnimationCompiler.Sampler sampler=SketchAnimationCompiler.prepare(source,p);for(int frame:new int[]{0,24,47,72,95}){JSONObject preview=sampler.preview(frame,id).getJSONObject("document");try(SketchFrameRenderer a=new SketchFrameRenderer(c,preview);SketchFrameRenderer b=new SketchFrameRenderer(c,compiled)){android.graphics.Bitmap x=a.render(0,false),y=b.render(frame,false);try{int[] actual=new int[256*256],wanted=new int[actual.length];x.getPixels(actual,0,256,0,0,256,256);y.getPixels(wanted,0,256,0,0,256,256);assertArrayEquals(actual,wanted);}finally{x.recycle();y.recycle();}}}
   String component="pose_"+java.util.UUID.randomUUID(),target="pose_target_"+java.util.UUID.randomUUID();SketchComponentLibrary.execute(c,"sketch_component_save",new JSONObject().put("componentId",component).put("sketchId",output).put("expectedRevision",1).put("operationId","component_save").put("name","Owned regional pose").put("category","pose").put("frameIndex",47));SketchEditOps.execute(c,"sketch_create",new JSONObject().put("sketchId",target).put("operationId","create").put("width",256).put("height",256).put("frameCount",1).put("background","#00000000"));SketchComponentLibrary.execute(c,"sketch_component_apply",new JSONObject().put("componentId",component).put("sketchId",target).put("expectedRevision",1).put("operationId","place").put("frameIndex",0).put("exposure",1));JSONObject staticPose=SketchPaintMeshTest.load(c,target);try(SketchFrameRenderer a=new SketchFrameRenderer(c,staticPose);SketchFrameRenderer b=new SketchFrameRenderer(c,compiled)){android.graphics.Bitmap x=a.render(0,false),y=b.render(47,false);try{int[] actual=new int[256*256],wanted=new int[actual.length];x.getPixels(actual,0,256,0,0,256,256);y.getPixels(wanted,0,256,0,0,256,256);assertArrayEquals(actual,wanted);}finally{x.recycle();y.recycle();}}
   JSONObject large=SketchDocument.copy(source);SketchDocument.object(large,"paint").put("paintMesh",SketchPaintMesh.regular(16,16));JSONObject longProgram=SketchDocument.copy(p).put("frameCount",1200);assertThrows(IllegalArgumentException.class,()->SketchAnimationCompiler.compile(large,longProgram,"oversized_bake"));return null;
  }catch(Exception failure){throw new RuntimeException(failure);}}).get(90,java.util.concurrent.TimeUnit.SECONDS);}finally{worker.shutdownNow();}
 }
 @Test public void regionalPressureStrokePublicationAndExactRetryKeepTheSerializedDocumentIdentity()throws Exception {
  java.util.concurrent.ExecutorService worker=java.util.concurrent.Executors.newSingleThreadExecutor();try{worker.submit(()->{try{
   android.content.Context c=RuntimeEnvironment.getApplication();String id="region_stroke_"+java.util.UUID.randomUUID(),animation=id+"_motion",output=id+"_baked";SketchEditOps.execute(c,"sketch_create",new JSONObject().put("sketchId",id).put("operationId","create").put("width",256).put("height",256).put("frameCount",1));JSONObject ink=line().put("id","ink");SketchPaintMeshTest.edit(c,id,1,"owned_pencil",new JSONArray().put(new JSONObject().put("type","add_object").put("layerId","layer_1").put("object",ink)));JSONObject source=SketchPaintMeshTest.load(c,id),p=program();String sourceCanonical=SketchDocument.canonical(source),programCanonical=SketchDocument.canonical(p);
   SketchAnimationOps.execute(c,"sketch_animation_save",new JSONObject().put("animationId",animation).put("sketchId",id).put("sourceRevision",2).put("expectedRevision",0).put("operationId","save").put("program",p));JSONObject request=new JSONObject().put("animationId",animation).put("expectedRevision",1).put("operationId","bake").put("outputSketchId",output),receipt=SketchAnimationOps.execute(c,"sketch_animation_bake",request),baked=SketchPaintMeshTest.load(c,output);assertEquals(96,baked.getJSONArray("layers").getJSONObject(0).getJSONArray("objects").length());assertEquals(receipt.getString("documentSha256"),SketchDocument.sha256(SketchDocument.canonical(baked).getBytes(java.nio.charset.StandardCharsets.UTF_8)));assertEquals(SketchDocument.canonical(receipt),SketchDocument.canonical(SketchAnimationOps.execute(c,"sketch_animation_bake",request)));assertEquals(sourceCanonical,SketchDocument.canonical(SketchPaintMeshTest.load(c,id)));assertEquals(programCanonical,SketchDocument.canonical(p));return null;
  }catch(Exception failure){throw new RuntimeException(failure);}}).get(90,java.util.concurrent.TimeUnit.SECONDS);}finally{worker.shutdownNow();}
 }

}
